mapper.select:
SELECT * FROM (SELECT T.* FROM( SELECT #{effectFlag} effectFlag, bobrt.BID_MODLE bidModle, bobrt.IS_WIN isWin, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, decode(ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7) entrustStatusOrder, ETR_ENTRUST.ENTRUST_TYPE entrustType, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, su1.real_name invManagerName, CASE WHEN det.PORTFOLIO_ID IS NULL THEN ETR_ENTRUST.PORTFOLIO_ID ELSE det.PORTFOLIO_ID END AS portfolioId, CASE WHEN det.PORTFOLIO_NAME IS NULL THEN PTL_PORTFOLIO.portfolio_name ELSE det.portfolio_name END AS portfolioName, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND fpt.TYPE_9 = '01' THEN 'F21' ELSE ETR_ENTRUST_ADD.ASSET_TYPE END AS finprodType2, case when FIN_PRODUCT_ISSUE.ISSUE_CLASS = '01' THEN to_char(FIN_PRODUCT_ISSUE.ISSUE_DATE, 'yyyy-mm-dd') when FIN_PRODUCT_ISSUE.ISSUE_DATE is not null then to_char(FIN_PRODUCT_ISSUE.ISSUE_DATE, 'yyyy-mm-dd') else to_char(FIN_PRODUCT_ISSUE.TENDER_SDATE,'yyyy-MM-dd') || '~' || to_char(FIN_PRODUCT_ISSUE.TENDER_EDATE,'yyyy-MM-dd') end as issueDateStr, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN ('03', '04','T56','T93','T94','T95','T96') THEN ETR_ENTRUST_ADD.TERM_TYPE else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') THEN ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') AND ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)) entrustAmt, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) finishAmt, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, B.TRADER trader, B.realName realName, ETR_ENTRUST.REMARK remark, btm.busi_type busiTypePosition, nvl(ssa.sec_acct_name,ssall.secAcctName) secAcctId, DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01','','F07',ETR_ENTRUST_ADD.TERM_DAYS,'F10',ETR_ENTRUST_ADD.TERM_DAYS,'F12',ETR_ENTRUST_ADD.TERM_DAYS,'F16',ETR_ENTRUST_ADD.TERM_DAYS,'') termDays, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS = '01' THEN case when FIN_PRODUCT.COUPON_SPECIES = '01' AND FIN_PRODUCT_ISSUE.INT_TYPE = '02' AND SDLDATA.ITEM_VALUE IS NOT NULL AND FIN_PRODUCT_ISSUE.bp IS NOT NULL THEN SDLDATA.ITEM_VALUE || '+' || to_char(FIN_PRODUCT_ISSUE.bp * 10000 ,'FM999,999,999,999,990.90') || ' BP' WHEN FIN_PRODUCT_ISSUE.REFER_YIELD IS NOT NULL THEN to_char(FIN_PRODUCT_ISSUE.REFER_YIELD * 100 ,'FM999,999,999,999,990.9990') || ' %' END WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS IN ('02','03') THEN CASE WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '01' AND bobp.BID_PRICE IS NOT NULL THEN bobp.BID_PRICE || ' %' WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '02' AND bobp.BID_PRICE IS NOT NULL THEN bobp.BID_PRICE || ' 元' WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '03' AND bobp.BID_PRICE IS NOT NULL THEN bobp.BID_PRICE || ' BP' ELSE bobp.BID_PRICE END ELSE TO_CHAR(round(decode(btm.busi_type, '02', decode(ETR_ENTRUST_ADD.CALCULATE_FIELD, 'price', ETR_ENTRUST.PRICE, 'exerYield', ETR_ENTRUST_ADD.EXER_YIELD * 100, 'matureYield', ETR_ENTRUST_ADD.MATURE_YIELD * 100), '03', ETR_ENTRUST.PRICE, '05', ETR_ENTRUST.PRICE * 100, ''), 4),'FM999,999,999,999,990.9990') END AS etrPrice, case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' and ETR_ENTRUST.ENTRUST_NUM != 0 then trunc(nvl(NVL(T7.FINISH_AMT, 0)+ NVL(T5.ENT_FINISH_AMT*100, 0),0)/(ETR_ENTRUST.ENTRUST_NUM*100),4)*100 when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' and ETR_ENTRUST.ENTRUST_NUM = 0 then 0 when ETR_ENTRUST.ENTRUST_AMT = 0 then 0 else trunc(nvl(nvl(T7.FINISH_AMT, 0) + nvl(T5.Ent_Finish_Amt, 0), 0) / ETR_ENTRUST.ENTRUST_AMT,4) * 100 end as exeProgress,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' and ETR_ENTRUST.ENTRUST_NUM != 0 then trunc((NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/(ETR_ENTRUST.ENTRUST_NUM*100),4)*100 when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' and ETR_ENTRUST.ENTRUST_NUM = 0 then 0 when ETR_ENTRUST.ENTRUST_AMT = 0 then 0 else trunc((nvl(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + nvl(T6.FINISH_AMT, 0)) / ETR_ENTRUST.ENTRUST_AMT, 4) * 100 end as dealProgress,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then (NVL(T7.FINISH_AMT,0)+NVL(T5.ENT_FINISH_AMT*100,0))/10000 else round((NVL(T7.FINISH_AMT, 0) + NVL(T5.ENT_FINISH_AMT, 0))/10000,2) end as execFinishAmt,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then NVL(ETR_ENTRUST.ENTRUST_NUM, 0)/100 - NVL(T7.FINISH_AMT,0)/10000 - NVL(T5.ENT_FINISH_AMT,0)/100 else round((NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(T7.FINISH_AMT, 0) - NVL(T5.ENT_FINISH_AMT, 0))/10000,2) end as execRemainderAmt,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then ROUND(NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/10000 else ROUND((NVL(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + NVL(T6.FINISH_AMT, 0))/10000,2) end as transFinishAmt,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then NVL(ETR_ENTRUST.ENTRUST_NUM, 0)/100 - ROUND(NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/10000 else ROUND((NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + NVL(T6.FINISH_AMT, 0))/10000,2) end as transRemainderAmt, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi:ss') transmitTime, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi') transmitTimeSer, ETR_ENTRUST_ADD.CALCULATE_FIELD calculateField FROM (SELECT * FROM ETR_ENTRUST where ps in ('T01','T02','T03','03','04') and trade_market in ('01','02') ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ( SELECT listagg(ETR_ENTRUST_DETAIL.SEC_ACCT_ID, ',') WITHIN GROUP ( ORDER BY ETR_ENTRUST_DETAIL.SEC_ACCT_ID ) secAcctId, listagg(STL_SEC_ACCT_INFO.SEC_ACCT_NAME , ',') WITHIN GROUP( ORDER BY STL_SEC_ACCT_INFO.SEC_ACCT_NAME) secAcctName, ETR_ENTRUST_DETAIL.ENTRUST_ID AS ENTRUST_ID FROM ETR_ENTRUST_DETAIL LEFT JOIN STL_SEC_ACCT_INFO ON STL_SEC_ACCT_INFO.SEC_ACCT_ID = ETR_ENTRUST_DETAIL.SEC_ACCT_ID GROUP BY ENTRUST_ID) ssall ON ssall.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID LEFT JOIN ( SELECT ENTRUST_ID, wm_concat ( ETR_ENTRUST_DETAIL.PORTFOLIO_ID ) PORTFOLIO_ID, wm_concat ( PORTFOLIO_NAME ) PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL LEFT JOIN (select PORTFOLIO_ID,PORTFOLIO_NAME from PTL_PORTFOLIO order by PORTFOLIO_ID, PORTFOLIO_NAME) PTL_PORTFOLIO ON ETR_ENTRUST_DETAIL.portfolio_id = PTL_PORTFOLIO.portfolio_id GROUP BY ENTRUST_ID ) det on det.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ( select ENTRUST_ID ,PORTFOLIO_ID from(select ol.ENTRUST_ID,ol.PORTFOLIO_ID, row_number() OVER(PARTITION BY ol.ENTRUST_ID ORDER BY ol.ENTRUST_ID) ds from ETR_ENTRUST_DETAIL ol where ol.ENTRUST_ID is not null) where ds = 1 ) det2 ON det2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON (PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID OR PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID = det2.PORTFOLIO_ID)
LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE ON FIN_PRODUCT_ISSUE.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (select listagg(case when t3.TENDER_TARGET = '01' then to_char(t0.BID_PRICE * 100, 'FM999,999,999,999,990.9990') when t3.TENDER_TARGET = '02' then to_char(t0.BID_PRICE, 'FM999,999,999,999,990.9990') when t3.TENDER_TARGET = '03' then to_char(t0.BID_PRICE * 10000, 'FM999,999,999,999,990.90') end, ',') within group (order by t0.ENTRUST_ID) AS BID_PRICE, t0.ENTRUST_ID from ETR_ENTRUST_BID_PRICE t0 LEFT JOIN ETR_ENTRUST t1 on t1.ENTRUST_ID = t0.ENTRUST_ID LEFT JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = t1.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE t3 ON t3.FINPROD_ID = t2.FINPROD_ID group by t0.ENTRUST_ID) bobp ON bobp.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (select * from SYS_DATADICT_LIST where DICT_CODE='SECRATE_DATA') SDLDATA on FIN_PRODUCT_ISSUE.INT_RATE_ID = SDLDATA.ITEM_CODE LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT,SUM(Ent_Finish_Amt) as Ent_Finish_Amt FROM ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T7 ON ETR_ENTRUST.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN(SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS INNER JOIN (SELECT DISTINCT T3.TRADE_ID FROM TRDQUTO_MATCH_INFO T1 INNER JOIN REG_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.PRE_TRADE_ID = T2.TOTLE_TRADE_ID INNER JOIN TRD_PRODUCT_DEAL T3 ON T3.TOTLE_TRADE_ID = T1.TRD_ID WHERE TRD_CONF_STATUS = '1') REG ON REG.TRADE_ID = ETR_FINISH_STATUS.TRADE_ID GROUP BY ENTRUST_ID) T6 ON ETR_ENTRUST.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, SUM(nvl(iqer.FPRICE_AMT, 0)) totalShareAmt FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07') GROUP BY iqer.ENTRUST_ID) C /*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/ ON C.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, iqer.FPRICE_AMT FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07')) C2/*质押式回购银行间报价*/ ON C2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT C.ENTRUST_ID, SUM(nvl(C.SHARE_AMT, 0)) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE C ON A.QUOTE_ID = C.QUOTE_ID WHERE B.TRADE_STATUS = '07' GROUP BY C.ENTRUST_ID) CB ON CB.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT A.ENTRUST_ID, nvl(A.SHARE_AMT, 0) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID WHERE B.TRADE_STATUS = '07') C2B ON C2B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join STL_SEC_ACCT_INFO ssa ON ETR_ENTRUST_ADD.SEC_ACCT_ID = ssa.SEC_ACCT_ID LEFT JOIN SYS_USER su1 ON ETR_ENTRUST.INV_MANAGER_ID = su1.USER_NAME LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps,INPUT_VALUE_3 as issueClass,OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON ETR_ENTRUST_ADD.ASSET_TYPE = btm.Finprod_Type_Tg AND ETR_ENTRUST.Ps = btm.ps AND ((ETR_ENTRUST.FINPROD_TYPE2 = 'F32' and btm.issueClass = FIN_PRODUCT_ISSUE.ISSUE_CLASS) or ETR_ENTRUST.FINPROD_TYPE2 != 'F32' and btm.issueClass is null) LEFT JOIN ( SELECT bo.BID_MODLE, brt.IS_WIN ,bo.FINPROD_ID ,bobp.ENTRUST_ID FROM BID_ORDER bo LEFT JOIN BID_ORDER_BID_PRICE bobp ON bobp.BID_ID = bo.BID_ID LEFT JOIN BID_RESULT_TOTAL brt ON brt.BID_ID = bo.BID_ID AND brt.STATUS = '01' AND brt.FINPROD_ID = bo.FINPROD_ID WHERE bo.IS_CANCEL = 'N' AND bo.TRADE_STATUS = '01' GROUP BY bo.BID_MODLE, brt.IS_WIN, bo.FINPROD_ID,bobp.ENTRUST_ID ) bobrt ON bobrt.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND bobrt.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustDistribute},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn},#{entrustRecall},#{entrustInwfl})
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
)
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND btm.busi_type = #{busiTypePosition}
AND FIN_PRODUCT.FINPROD_MARKET_ID IN(
#{item}
)
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND ETR_ENTRUST_ADD.SEC_ACCT_ID IN(
#{item}
)
AND ETR_ENTRUST.ENTRUST_ID LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
AND ETR_ENTRUST.INV_MANAGER_ID IN(
#{item}
)
AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustStartDate} AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') <= #{entrustEndDate}
AND ETR_ENTRUST.CCY = #{ccy}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
union all SELECT #{effectFlag04} effectFlag, null as bidModle, null as isWin, WFL_ETR_ENTRUST.ENTRUST_STATUS entrustStatus, decode(WFL_ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7) entrustStatusOrder, WFL_ETR_ENTRUST.ENTRUST_TYPE entrustType, WFL_ETR_ENTRUST.ENTRUST_ID entrustId, WFL_ETR_ENTRUST.INV_MANAGER_ID invManagerId, su1.real_name invManagerName, CASE WHEN det.PORTFOLIO_ID IS NULL THEN WFL_ETR_ENTRUST.PORTFOLIO_ID ELSE det.PORTFOLIO_ID END AS portfolioId, CASE WHEN det.PORTFOLIO_NAME IS NULL THEN PTL_PORTFOLIO.portfolio_name ELSE det.portfolio_name END AS portfolioName, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND fpt.TYPE_9 = '01' THEN 'F21' ELSE WFL_ETR_ENTRUST_ADD.ASSET_TYPE END AS finprodType2, case when FIN_PRODUCT_ISSUE.ISSUE_CLASS = '01' THEN to_char(FIN_PRODUCT_ISSUE.ISSUE_DATE, 'yyyy-mm-dd') when FIN_PRODUCT_ISSUE.ISSUE_DATE is not null then to_char(FIN_PRODUCT_ISSUE.ISSUE_DATE, 'yyyy-mm-dd') else to_char(FIN_PRODUCT_ISSUE.TENDER_SDATE,'yyyy-MM-dd') || '~' || to_char(FIN_PRODUCT_ISSUE.TENDER_EDATE,'yyyy-MM-dd') end as issueDateStr, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN ('03', '04','T56','T93','T94','T95','T96') THEN WFL_ETR_ENTRUST_ADD.TERM_TYPE else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else WFL_ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN('03','04') THEN WFL_ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN('03','04') AND WFL_ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN WFL_ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, WFL_ETR_ENTRUST.PS Ps, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = WFL_ETR_ENTRUST_ADD.BUSI_PS) WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = WFL_ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = WFL_ETR_ENTRUST.PS) END AS otherPs, WFL_ETR_ENTRUST_ADD.BUSI_PS busiPs, WFL_ETR_ENTRUST.TRADE_MARKET tradeMarket, decode(WFL_ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(WFL_ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(WFL_ETR_ENTRUST.ENTRUST_NUM * 100,0),NVL(WFL_ETR_ENTRUST.ENTRUST_AMT,WFL_ETR_ENTRUST.ENTRUST_NUM)) entrustAmt, decode(WFL_ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) finishAmt, WFL_ETR_ENTRUST.CCY ccy, WFL_ETR_ENTRUST.ENTRUST_DATE entrustDate, WFL_ETR_ENTRUST.VDATE vdate, WFL_ETR_ENTRUST.MDATE mdate, B.TRADER trader, B.realName realName, WFL_ETR_ENTRUST.REMARK remark, btm.busi_type busiTypePosition, nvl(ssa.sec_acct_name,ssall.secAcctName) secAcctId, DECODE(WFL_ETR_ENTRUST_ADD.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, decode(WFL_ETR_ENTRUST_ADD.ASSET_TYPE,'F01','','F07',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F10',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F12',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F16',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'') termDays, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS = '01' THEN case when FIN_PRODUCT.COUPON_SPECIES = '01' AND FIN_PRODUCT_ISSUE.INT_TYPE = '02' AND SDLDATA.ITEM_VALUE IS NOT NULL AND FIN_PRODUCT_ISSUE.bp IS NOT NULL THEN SDLDATA.ITEM_VALUE || '+' || to_char(FIN_PRODUCT_ISSUE.bp * 10000 ,'FM999,999,999,999,990.90') || ' BP' WHEN FIN_PRODUCT_ISSUE.REFER_YIELD IS NOT NULL THEN to_char(FIN_PRODUCT_ISSUE.REFER_YIELD * 100 ,'FM999,999,999,999,990.9990') || ' %' END WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND FIN_PRODUCT_ISSUE.ISSUE_CLASS IN ('02','03') THEN CASE WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '01' AND bobp.BID_PRICE IS NOT NULL THEN bobp.BID_PRICE || ' %' WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '02' AND bobp.BID_PRICE IS NOT NULL THEN bobp.BID_PRICE || ' 元' WHEN FIN_PRODUCT_ISSUE.TENDER_TARGET = '03' AND bobp.BID_PRICE IS NOT NULL THEN bobp.BID_PRICE || ' BP' ELSE bobp.BID_PRICE END ELSE TO_CHAR(round(decode(btm.busi_type,#{busiTypePosition02},decode(WFL_ETR_ENTRUST_ADD.CAL_MODE,'price',WFL_ETR_ENTRUST.PRICE,'exerYield',WFL_ETR_ENTRUST_ADD.EXER_YIELD*100,'matureYield',WFL_ETR_ENTRUST_ADD.MATURE_YIELD*100),#{busiTypePosition03},WFL_ETR_ENTRUST.PRICE,#{busiTypePosition05},WFL_ETR_ENTRUST.PRICE*100,''),4),'FM999,999,999,999,990.9990') END AS etrPrice, case when WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' and WFL_ETR_ENTRUST.ENTRUST_NUM != 0 then trunc(nvl(NVL(T7.FINISH_AMT, 0)+ NVL(T5.ENT_FINISH_AMT*100, 0),0)/(WFL_ETR_ENTRUST.ENTRUST_NUM*100),4)*100 when WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' and WFL_ETR_ENTRUST.ENTRUST_NUM = 0 then 0 when WFL_ETR_ENTRUST.ENTRUST_AMT = 0 then 0 else trunc(nvl(nvl(T7.FINISH_AMT, 0) + nvl(T5.Ent_Finish_Amt, 0), 0) / WFL_ETR_ENTRUST.ENTRUST_AMT,4) * 100 end as exeProgress,
case when WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' and WFL_ETR_ENTRUST.ENTRUST_NUM != 0 then trunc((NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/(WFL_ETR_ENTRUST.ENTRUST_NUM*100),4)*100 when WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' and WFL_ETR_ENTRUST.ENTRUST_NUM = 0 then 0 when WFL_ETR_ENTRUST.ENTRUST_AMT = 0 then 0 else trunc((nvl(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + nvl(T6.FINISH_AMT, 0)) / WFL_ETR_ENTRUST.ENTRUST_AMT, 4) * 100 end as dealProgress,
case when WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then (NVL(T7.FINISH_AMT,0)+NVL(T5.ENT_FINISH_AMT*100,0))/10000 else (NVL(T7.FINISH_AMT, 0) + NVL(T5.ENT_FINISH_AMT, 0))/10000 end as execFinishAmt,
case when WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then NVL(WFL_ETR_ENTRUST.ENTRUST_NUM, 0)/100 - NVL(T7.FINISH_AMT,0)/10000 - NVL(T5.ENT_FINISH_AMT,0)/100 else ROUND((NVL(WFL_ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(T7.FINISH_AMT, 0) - NVL(T5.ENT_FINISH_AMT, 0))/10000,2) end as execRemainderAmt,
case when WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then ROUND((NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/10000,2) else ROUND((NVL(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + NVL(T6.FINISH_AMT, 0))/10000,2) end as transFinishAmt,
case when WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then NVL(WFL_ETR_ENTRUST.ENTRUST_NUM, 0)/100 - ROUND(NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/10000 else (NVL(WFL_ETR_ENTRUST.ENTRUST_AMT, 0) - ROUND(NVL(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + NVL(T6.FINISH_AMT, 0)))/10000 end as transRemainderAmt, NULL transmitTime, NULL transmitTimeSer, WFL_ETR_ENTRUST_ADD.CAL_MODE calculateField FROM (SELECT * FROM WFL_ETR_ENTRUST where ps in ('T01','T02','T03','03','04') and trade_market in ('01','02') ORDER BY ENTRUST_DATE DESC) WFL_ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = WFL_ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = WFL_ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN ( SELECT listagg(ETR_ENTRUST_DETAIL.SEC_ACCT_ID, ',') WITHIN GROUP ( ORDER BY ETR_ENTRUST_DETAIL.SEC_ACCT_ID ) secAcctId, listagg(STL_SEC_ACCT_INFO.SEC_ACCT_NAME , ',') WITHIN GROUP( ORDER BY STL_SEC_ACCT_INFO.SEC_ACCT_NAME) secAcctName, ETR_ENTRUST_DETAIL.ENTRUST_ID AS ENTRUST_ID FROM ETR_ENTRUST_DETAIL LEFT JOIN STL_SEC_ACCT_INFO ON STL_SEC_ACCT_INFO.SEC_ACCT_ID = ETR_ENTRUST_DETAIL.SEC_ACCT_ID GROUP BY ENTRUST_ID) ssall ON ssall.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN WFL_ETR_ENTRUST_ADD ON WFL_ETR_ENTRUST.ENTRUST_ID = WFL_ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON WFL_ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = WFL_ETR_ENTRUST.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE ON FIN_PRODUCT_ISSUE.FINPROD_ID = WFL_ETR_ENTRUST.FINPROD_ID LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps,INPUT_VALUE_3 as issueClass,OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON WFL_ETR_ENTRUST_ADD.ASSET_TYPE = btm.Finprod_Type_Tg AND wfl_ETR_ENTRUST.Ps = btm.ps AND ((WFL_ETR_ENTRUST.FINPROD_TYPE2 = 'F32' and btm.issueClass = FIN_PRODUCT_ISSUE.ISSUE_CLASS) or WFL_ETR_ENTRUST.FINPROD_TYPE2 != 'F32' and btm.issueClass is null) LEFT JOIN ( SELECT ENTRUST_ID, wm_concat ( WFL_ETR_ENTRUST_DETAIL.PORTFOLIO_ID ) PORTFOLIO_ID, wm_concat ( PORTFOLIO_NAME ) PORTFOLIO_NAME FROM WFL_ETR_ENTRUST_DETAIL LEFT JOIN (select PORTFOLIO_ID,PORTFOLIO_NAME from PTL_PORTFOLIO order by PORTFOLIO_ID, PORTFOLIO_NAME) PTL_PORTFOLIO ON WFL_ETR_ENTRUST_DETAIL.portfolio_id = PTL_PORTFOLIO.portfolio_id GROUP BY ENTRUST_ID ) det on det.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (select ENTRUST_ID ,PORTFOLIO_ID from(select ol.ENTRUST_ID,ol.PORTFOLIO_ID, row_number() OVER(PARTITION BY ol.ENTRUST_ID ORDER BY ol.ENTRUST_ID) ds from WFL_ETR_ENTRUST_DETAIL ol where ol.ENTRUST_ID is not null) where ds = 1 ) det2 ON det2.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON (PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID OR PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID = det2.PORTFOLIO_ID)
LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (select listagg(case when t3.TENDER_TARGET = '01' then to_char(t0.BID_PRICE * 100, 'FM999,999,999,999,990.9990') when t3.TENDER_TARGET = '02' then to_char(t0.BID_PRICE, 'FM999,999,999,999,990.9990') when t3.TENDER_TARGET = '03' then to_char(t0.BID_PRICE * 10000, 'FM999,999,999,999,990.90') end, ',') within group (order by t0.ENTRUST_ID) AS BID_PRICE, t0.ENTRUST_ID from WFL_ETR_ENTRUST_BID_PRICE t0 LEFT JOIN WFL_ETR_ENTRUST t1 on t1.ENTRUST_ID = t0.ENTRUST_ID LEFT JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = t1.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE t3 ON t3.FINPROD_ID = t2.FINPROD_ID group by t0.ENTRUST_ID) bobp ON bobp.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (select * from SYS_DATADICT_LIST where DICT_CODE='SECRATE_DATA') SDLDATA on FIN_PRODUCT_ISSUE.INT_RATE_ID = SDLDATA.ITEM_CODE LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT,SUM(Ent_Finish_Amt) as Ent_Finish_Amt FROM ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) T5 ON WFL_ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T7 ON WFL_ETR_ENTRUST.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN(SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS INNER JOIN (SELECT DISTINCT T3.TRADE_ID FROM TRDQUTO_MATCH_INFO T1 INNER JOIN REG_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.PRE_TRADE_ID = T2.TOTLE_TRADE_ID INNER JOIN TRD_PRODUCT_DEAL T3 ON T3.TOTLE_TRADE_ID = T1.TRD_ID WHERE TRD_CONF_STATUS = '1') REG ON REG.TRADE_ID = ETR_FINISH_STATUS.TRADE_ID GROUP BY ENTRUST_ID) T6 ON WFL_ETR_ENTRUST.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, SUM(nvl(iqer.FPRICE_AMT, 0)) totalShareAmt FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07') GROUP BY iqer.ENTRUST_ID) C /*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/ ON C.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, iqer.FPRICE_AMT FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07')) C2/*质押式回购银行间报价*/ ON C2.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT C.ENTRUST_ID, SUM(nvl(C.SHARE_AMT, 0)) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE C ON A.QUOTE_ID = C.QUOTE_ID WHERE B.TRADE_STATUS = '07' GROUP BY C.ENTRUST_ID) CB ON CB.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT A.ENTRUST_ID, nvl(A.SHARE_AMT, 0) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID WHERE B.TRADE_STATUS = '07') C2B ON C2B.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID left join STL_SEC_ACCT_INFO ssa ON WFL_ETR_ENTRUST_ADD.SEC_ACCT_ID = ssa.SEC_ACCT_ID LEFT JOIN SYS_USER su1 ON WFL_ETR_ENTRUST.INV_MANAGER_ID = su1.USER_NAME
AND WFL_ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND WFL_ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
)
AND (case
when WFL_ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then WFL_ETR_ENTRUST_ADD.BUSI_PS
when WFL_ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then WFL_ETR_ENTRUST_ADD.BUSI_PS
else WFL_ETR_ENTRUST.PS end) =#{ps}
AND WFL_ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND btm.busi_type = #{busiTypePosition}
AND FIN_PRODUCT.FINPROD_MARKET_ID IN(
#{item}
)
AND WFL_ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND WFL_ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND WFL_ETR_ENTRUST_ADD.SEC_ACCT_ID IN(
#{item}
)
AND WFL_ETR_ENTRUST.ENTRUST_ID LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
AND WFL_ETR_ENTRUST.INV_MANAGER_ID IN(
#{item}
)
AND to_char(WFL_ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustStartDate} AND to_char(WFL_ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') <= #{entrustEndDate}
AND WFL_ETR_ENTRUST.CCY = #{ccy}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
) t left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE='STATUS_VALID' and t.effectFlag=sdl.ITEM_CODE left join SYS_DATADICT_LIST sdl1 on sdl1.DICT_CODE='ENTRUST_STATUS' and t.entrustStatus=sdl1.ITEM_CODE left join SYS_DATADICT_LIST sdl2 on sdl2.DICT_CODE='PINAN_ASSET_TYPE' and t.finprodType2=sdl2.ITEM_CODE left join SYS_DATADICT_LIST sdl3 on sdl3.DICT_CODE='BUSI_TYPE_POSITION' and t.busiTypePosition=sdl3.ITEM_CODE left join SYS_DATADICT_LIST sdl4 on sdl4.DICT_CODE='PS' and t.PS=sdl4.ITEM_CODE left join SYS_DATADICT_LIST sdl5 on sdl5.DICT_CODE='TRADE_MARKET' and t.tradeMarket=sdl5.ITEM_CODE left join SYS_DATADICT_LIST sdl6 on sdl6.DICT_CODE='ACCOUNT_SPEED' and t.settleSpeed=sdl6.ITEM_CODE left join SYS_DATADICT_LIST sdl7 on sdl7.DICT_CODE='CCY' and t.ccy=sdl7.ITEM_CODE
order by t.finprodType2,t.entrustStatusOrder,t.busiTypePosition,t.ps)
order by ${sort} ${direction}

if.where:
(sdl.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl1.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl2.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl3.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl4.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl5.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl6.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl7.ITEM_VALUE like '%' || #{search} || '%'
    OR t.entrustId like '%' || #{search} || '%'
    OR t.invManagerId like '%' || #{search} || '%'
    OR t.invManagerName like '%' || #{search} || '%'
    OR t.realName like '%' || #{search} || '%'
    OR t.trader like '%' || #{search} || '%'
    OR t.portfolioId like '%' || #{search} || '%'
    OR t.portfolioName like '%' || #{search} || '%'
    OR t.finprodMarketId like '%' || #{search} || '%'
    OR t.finprodAbbr like '%' || #{search} || '%'
    OR t.remark like '%' || #{search} || '%'
    OR t.secAcctId like '%' || #{search} || '%'
    OR t.entrustAmt||'' = #{search}
    OR t.etrPrice||'' = #{search}
    OR t.termDays||'' = #{search}
    OR t.exeProgress||'' = #{search}
    OR t.dealProgress||'' = #{search}
    OR TO_CHAR(t.entrustDate,'yyyy-MM-dd') ||''= #{search}
    OR TO_CHAR(t.entrustDate,'yyyy-MM-dd') ||''= #{year}||'-'||#{search}
    OR replace(TO_CHAR(t.entrustDate,'yyyy-MM-dd'),'-','/')=#{search}
    OR replace(TO_CHAR(t.entrustDate,'yyyy-MM-dd'),'-','/')=#{year}||'/'||#{search}
    OR t.transmitTime = #{search}
    OR t.transmitTimeSer = #{search}
    OR t.issueDateStr = #{search}
)
